import { $gl } from "../../WebGLUtil";
import { execute as textureManagerBind0UseCase } from "../../TextureManager/usecase/TextureManagerBind0UseCase";
import { $setFramebufferBound, $setCurrentAttachment, $readFrameBuffer, $useFramebufferBound } from "../../FrameBufferManager";
/**
 * @description フレームバッファにアタッチメントオブジェクトをバインドする
 *              Bind the attachment object to the frame buffer
 *
 * @param  {IAttachmentObject} attachment_object
 * @return {void}
 * @method
 * @protected
 */
export const execute = (attachment_object) => {
    $setCurrentAttachment(attachment_object);
    if (!$useFramebufferBound()) {
        $setFramebufferBound(true);
        $gl.bindFramebuffer($gl.FRAMEBUFFER, $readFrameBuffer);
    }
    if (attachment_object.msaa) {
        $gl.bindRenderbuffer($gl.RENDERBUFFER, attachment_object.color.resource);
        $gl.framebufferRenderbuffer($gl.FRAMEBUFFER, $gl.COLOR_ATTACHMENT0, $gl.RENDERBUFFER, attachment_object.color.resource);
    }
    else {
        textureManagerBind0UseCase(attachment_object.texture);
        $gl.framebufferTexture2D($gl.FRAMEBUFFER, $gl.COLOR_ATTACHMENT0, $gl.TEXTURE_2D, attachment_object.texture.resource, 0);
    }
    $gl.bindRenderbuffer($gl.RENDERBUFFER, attachment_object.stencil.resource);
    $gl.framebufferRenderbuffer($gl.FRAMEBUFFER, $gl.STENCIL_ATTACHMENT, $gl.RENDERBUFFER, attachment_object.stencil.resource);
};
